# =============================================================================
# app.R — App Shiny principal de CrackTime (Fase 4)
#
# TODO el cálculo corre client-side: en Shinylive (WASM) no hay servidor de R.
# La contraseña ingresada nunca sale del navegador (cero llamadas de red).
#
# NOTA de estructura: este archivo define `ui()` y `server()`. El archivo
# `app.R` en la raíz del repo es el entrypoint que los lanza con
# shiny::shinyApp(). Shiny/shinylive exigen app.R (o server.R) en la raíz del
# directorio de la app, así que el código vive acá y el launcher en la raíz.
# =============================================================================

source("R/entropy.R")
source("R/patterns.R")
source("R/suggestions.R")
source("R/fun_facts.R")

# --- Fortaleza (umbrales sobre la entropía AJUSTADA, no la teórica) -----------

# Umbrales en bits: 0-34 débil, 35-59 media, 60-79 fuerte, >=80 muy fuerte.
.UMBRAL_DEBIL  <- 35
.UMBRAL_MEDIA  <- 60
.UMBRAL_FUERTE <- 80

etiqueta_fortaleza <- function(bits) {
  if (is.na(bits)) return(list(texto = "no calculable", clase = "fuerza-na",
                               pct = 0, color = "#8b949e"))
  if (bits < .UMBRAL_DEBIL)  return(list(texto = "débil",   clase = "fuerza-debil",
                                         pct = 100 * bits / .UMBRAL_DEBIL,
                                         color = "#ff5d5d"))
  if (bits < .UMBRAL_MEDIA)  return(list(texto = "media",   clase = "fuerza-media",
                                         pct = 100 * bits / .UMBRAL_MEDIA,
                                         color = "#ffb020"))
  if (bits < .UMBRAL_FUERTE) return(list(texto = "fuerte",  clase = "fuerza-fuerte",
                                         pct = 100 * bits / .UMBRAL_FUERTE,
                                         color = "#58d68d"))
  list(texto = "muy fuerte", clase = "fuerza-muyfuerte",
       pct = 100, color = "#00e5a0")
}

# --- Tema bslib (paleta definida en Fase 5) ------------------------------------

# Tipografías embebidas localmente (www/fonts + @font-face en styles.css).
# NO usar bslib::font_google(): webR no tiene curl/libcurl y el intento de
# descarga en runtime rompe el render de la app.
.tema <- bslib::bs_theme(
  version = 5,
  bg = "#0b0f14",
  fg = "#e6edf3",
  primary = "#00e5a0",
  secondary = "#8b949e",
  success = "#58d68d",
  info = "#58a6ff",
  warning = "#ffb020",
  danger = "#ff5d5d",
  base_font = bslib::font_collection("Inter", "system-ui", "Segoe UI", "sans-serif"),
  heading_font = bslib::font_collection("Space Grotesk", "Inter", "sans-serif"),
  code_font = bslib::font_collection("JetBrains Mono", "Consolas", "monospace")
)

# --- UI ------------------------------------------------------------------------

ui <- function() {
  bslib::page_fluid(
    theme = .tema,
    lang = "es",
    tags$head(
      tags$link(rel = "icon", type = "image/svg+xml",
                href = "assets/favicon.svg"),
      tags$link(rel = "stylesheet", href = "styles.css"),
      tags$script(HTML(
        "document.addEventListener('DOMContentLoaded', function() {
           var cb = document.getElementById('mostrar');
           var el = document.getElementById('password');
           if (cb && el) {
             cb.addEventListener('change', function() {
               // Toggle 100% client-side (visual puro): basado en cb.checked,
               // sin depender del estado .type (el binding de Shiny lo deja
               // desincronizado entre propiedad y atributo).
               var n = cb.checked ? 'text' : 'password';
               el.setAttribute('type', n);
               el.type = n;
             });
           }
         });"
      )),
      tags$script(HTML(
        "Shiny.addCustomMessageHandler('estilo-fortaleza', function(st) {
           var bar = document.getElementById('barra-fortaleza');
           if (bar) {
             bar.style.width = st.width;
             bar.style.background = st.color;
           }
           var cont = document.getElementById('contenedor-fortaleza');
           if (cont) { cont.style.borderColor = st.color; }
         });"
      )),
      tags$script(HTML(
        "Shiny.addCustomMessageHandler('copiar-resumen', function(texto) {
           if (navigator.clipboard && navigator.clipboard.writeText) {
             navigator.clipboard.writeText(texto).then(function() {
               Shiny.setInputValue('copiado', Math.random());
             });
           }
         });"
      ))
    ),
    div(class = "contenedor",
      # Cabecera
      div(class = "cabecera",
        h1(class = "titulo", "CrackTime"),
        p(class = "subtitulo",
          "¿Cuánto tardaría una computadora en descifrar tu contraseña por fuerza bruta?")
      ),

      # Banner de privacidad (siempre visible, arriba)
      div(class = "banner-privacidad",
        icon("lock"),
        span("Tu contraseña nunca se envía a ningún servidor — todo el cálculo
              ocurre en tu navegador. Es privado de verdad, no es marketing.")),

      # Input
      div(class = "tarjeta",
        h2(class = "tarjeta-titulo", "Tu contraseña"),
        div(class = "fila-input",
          (function() {
            pw <- passwordInput("password", NULL,
                                placeholder = "Escribí tu contraseña…",
                                width = "100%")
            # A11y: el label es NULL (el título del card cumple ese rol);
            # el input lleva aria-label para lectores de pantalla.
            pw$children[[2]]$attribs[["aria-label"]] <- "Tu contraseña"
            pw
          })(),
          checkboxInput("mostrar", "Mostrar", width = "100%")
        ),
        div(class = "fortaleza",
          div(id = "contenedor-fortaleza", class = "contenedor-fortaleza",
            div(id = "barra-fortaleza", class = "barra-fortaleza"))
        ),
        uiOutput("etiqueta_fortaleza")
      ),

      # Resultado principal (hero)
      div(id = "panel-resultado", class = "tarjeta tarjeta-resultado",
        h2(class = "tarjeta-titulo", "Tiempo estimado de crackeo"),
        div(class = "hero-tiempo", textOutput("tiempo_hero", inline = TRUE)),
        div(class = "hero-nota", textOutput("tiempo_nota", inline = TRUE)),

        # Escenario de ataque
        radioButtons("escenario", "Escenario de ataque",
          choiceNames = c("GPU moderna (offline)", "Ataque online (con límite)",
                          "Cluster / nube masiva"),
          choiceValues = c("gpu", "online", "cluster"),
          selected = "gpu", inline = TRUE),

        div(class = "detalles-tecnicos", htmlOutput("detalles"))
      ),

      # Dato curioso
      div(id = "panel-dato", class = "tarjeta tarjeta-dato",
        div(class = "dato-icono", icon("lightbulb")),
        div(class = "dato-cuerpo",
          h2(class = "tarjeta-titulo", "Para que te hagas una idea…"),
          div(class = "dato-texto", textOutput("dato_texto", inline = TRUE)))
      ),

      # Sugerencias
      div(id = "panel-sugerencias", class = "tarjeta",
        h2(class = "tarjeta-titulo", "Cómo mejorarla"),
        uiOutput("sugerencias")
      ),

      # Compartir
      div(class = "tarjeta compartir",
        actionButton("compartir", "Copiar resumen para compartir",
                     class = "btn-compartir", icon = icon("share-nodes")),
        div(class = "compartir-nota", textOutput("compartir_nota", inline = TRUE))
      ),

      # Pie
      div(class = "pie",
        p("Estimación para fuerza bruta a 10^10 intentos/segundo (GPU moderna).
           No asume hashes lentos (bcrypt/argon2). Resultado educativo,
           calculado 100% en tu navegador.")
      )
    )
  )
}

# --- Cálculo central (lógica pura, testeable sin Shiny) -------------------------
# Devuelve el resultado completo para una contraseña y un escenario de ataque.
# El server solo lo conecta a reactividad; esta función es síncrona y pura.
calcular_resultado <- function(password, escenario = "gpu") {
  p <- password %||% ""
  if (nchar(p) == 0L) return(NULL)
  velocidad <- VELOCIDADES_ATAQUE[[escenario]]
  ent <- calcular_entropia(p)
  tiempo <- tiempo_estimado(ent, velocidad)
  list(
    password = p,
    entropia = ent,
    tiempo = tiempo,
    fortaleza = etiqueta_fortaleza(ent$entropia_ajustada_bits),
    sugerencias = generar_sugerencias(p),
    dato = dato_curioso(tiempo),
    escenario = escenario
  )
}

# --- Server ----------------------------------------------------------------------

server <- function(input, output, session) {
  # Toggle mostrar/ocultar: el cambio de type es 100% client-side (ver JS en la
  # UI). Acá solo se actualiza el texto del label vía el binding de Shiny.
  observeEvent(input$mostrar, {
    updateCheckboxInput(session, "mostrar",
                        label = if (input$mostrar) "Ocultar" else "Mostrar")
  })

  # Reactividad en vivo con debounce (~200 ms).
  # Se implementa con `later` en vez de shiny::debounce() porque el debounce
  # nativo crea un dominio reactivo interno que rompe testServer() (y esta
  # versión es testeable con later::run_now()).
  pw <- reactive({ input$password %||% "" })
  pw_deb <- reactiveVal("")
  .timer_debounce <- NULL
  observeEvent(pw(), {
    if (!is.null(.timer_debounce)) .timer_debounce()  # later() devuelve una función de cancelación
    .timer_debounce <<- later::later(function() {
      isolate(pw_deb(pw()))
    }, 0.2)
  }, ignoreNULL = FALSE)

  # Cálculo central (entropía + tiempo + sugerencias + dato)
  resultado <- reactive({
    calcular_resultado(pw_deb(), input$escenario)
  })

  # Barra de fortaleza
  observe({
    r <- resultado()
    session$sendCustomMessage("estilo-fortaleza",
      if (is.null(r)) list(width = "0%", color = "#8b949e")
      else list(width = paste0(min(r$fortaleza$pct, 100), "%"),
                color = r$fortaleza$color))
  })

  # Fortaleza (texto)
  output$etiqueta_fortaleza <- renderUI({
    r <- resultado()
    if (is.null(r)) return(div(class = "fuerza-chip fuerza-na",
                               span("Escribí una contraseña")))
    div(class = paste("fuerza-chip", r$fortaleza$clase),
        span(r$fortaleza$texto))
  })

  # Tiempo hero
  output$tiempo_hero <- renderText({
    r <- resultado()
    if (is.null(r)) return("…")
    formatear_tiempo(r$tiempo$segundos, r$tiempo$log10_segundos)
  })

  output$tiempo_nota <- renderText({
    r <- resultado()
    if (is.null(r)) return("Escribí una contraseña para estimar el tiempo.")
    sprintf("para una contraseña de %d caracteres, en %s",
            r$entropia$longitud, input$escenario)
  })

  # Detalles técnicos
  output$detalles <- renderUI({
    r <- resultado()
    if (is.null(r)) return(NULL)
    e <- r$entropia
    if (is.na(e$entropia_ajustada_bits)) {
      return(tags$p(class = "detalle-na", e$nota %||% ""))
    }
    div(class = "detalles-fila",
      span(sprintf("Entropía teórica: <b>%.1f bits</b>", e$entropia_teorica_bits)),
      span(sprintf("Entropía ajustada: <b>%.1f bits</b>", e$entropia_ajustada_bits)),
      span(sprintf("Charset: %d", e$charset_size)),
      span(sprintf("Longitud: %d", e$longitud)),
      if (!is.null(e$nota)) span(class = "nota-unicode", e$nota)
    )
  })

  # Dato curioso
  output$dato_texto <- renderText({
    r <- resultado()
    if (is.null(r)) return("")
    r$dato$texto
  })
  outputOptions(output, "dato_texto", suspendWhenHidden = FALSE)

  # Sugerencias
  output$sugerencias <- renderUI({
    r <- resultado()
    if (is.null(r)) return(div(class = "sugerencia-vacia",
                               "Las sugerencias aparecerán acá."))
    lapply(seq_along(r$sugerencias), function(i) {
      s <- r$sugerencias[[i]]
      div(class = paste("sugerencia", "sugerencia-", s$tipo, sep = ""),
        div(class = "sugerencia-num", i),
        div(class = "sugerencia-cuerpo",
          strong(s$titulo),
          p(s$texto),
          div(class = "sugerencia-antes-despues",
            span(class = "badge-antes", s$antes),
            icon("arrow-right"),
            span(class = "badge-despues", s$despues)),
          if (nzchar(s$nota)) div(class = "sugerencia-nota", s$nota))
      )
    })
  })

  # Compartir: resumen sin la contraseña
  observeEvent(input$compartir, {
    r <- resultado()
    if (is.null(r)) return(NULL)
    resumen <- sprintf(
      "CrackTime: mi contraseña tardaría %s en descifrarse (según un ataque por fuerza bruta con GPU, %d caracteres). Dato: %s. ¿Cuánto tarda la tuya?",
      formatear_tiempo(r$tiempo$segundos, r$tiempo$log10_segundos),
      r$entropia$longitud, r$dato$texto
    )
    session$sendCustomMessage("copiar-resumen", resumen)
  })
  observeEvent(input$copiado, {
    output$compartir_nota <- renderText("¡Resumen copiado! Pegalo donde quieras.")
  })
}

# =============================================================================
# entropy.R — Lógica de cálculo de entropía y tiempo de crackeo (Fase 2)
#
# Diseño del modelo (documentado para mantener honestidad del resultado):
#   * Entropía teórica:  bits = longitud * log2(charset_size)
#   * Entropía ajustada: bits_teoricos - penalizacion_por_patrones
#     (la penalización está definida en patterns.R)
#   * Trabajo SIEMPRE en escala logarítmica (log2 bits / log10 segundos) para
#     evitar overflow con contraseñas largas (charset^longitud no se calcula).
#   * Velocidad de ataque default: 10^10 intentos/segundo (ver VELOCIDAD_DEFAULT).
# =============================================================================

# --- Constantes documentadas -------------------------------------------------

# Conjunto exacto de 32 símbolos comunes (26 del prompt + 6 complementarios:
# ~ ` / \ " '). Orden y tamaño quedan fijados acá a propósito.
.SIMBOLOS_COMUNES <- "!@#$%^&*()_+-=[]{}|;:,.<>?~`/\\\"'"

# Tamaño de cada categoría de charset (RFC 4086 / práctica estándar).
.TAM_MINUSCULAS <- 26L
.TAM_MAYUSCULAS <- 26L
.TAM_NUMEROS    <- 10L
.TAM_SIMBOLOS   <- 32L

# Velocidad de ataque asumida (intentos por segundo).
# Justificación del default (10^10/s): ataque offline con GPU moderna sobre
# hashes rápidos (ej. NTLM/MD5) — Hashcat benchmark documentado en ~10^10
# hashes/s con un rig de varias RTX 4090 (ej. hashes.org / hashcat.net wiki,
# 2024-2025). Es una cota razonable y conservadora: NO asume hashes dedicados
# lentos (bcrypt/argon2 serían 10^5-10^6 veces más lentos).
VELOCIDAD_DEFAULT <- 1e10

# Escenarios alternativos de hardware (para mostrar 2-3 resultados).
VELOCIDADES_ATAQUE <- list(
  online = 1e3,      # ataque online con rate-limit (~1k intentos/s)
  gpu    = 1e10,     # ataque offline con GPU moderna (default)
  cluster = 1e13     # cluster / cloud cracking masivo
)

# Tope de bits para contraseñas que son esencialmente una palabra del
# diccionario embebido (top ~200 términos): log2(200) ≈ 7.64 → 8 bits.
.LIMITE_BITS_DICCIONARIO <- 8

# --- Charset ----------------------------------------------------------------

#' Detecta el conjunto de caracteres usado por la contraseña.
#' Devuelve lista con tamaño de charset, longitud y categorías detectadas.
#' Los caracteres Unicode no contemplados se reportan aparte y NO suman al
#' charset (no se asume un tamaño para ellos; ver `unicode_present`).
calcular_charset <- function(password) {
  pw <- as.character(password %||% "")
  chars <- strsplit(pw, "", fixed = TRUE)[[1]]
  simb <- strsplit(.SIMBOLOS_COMUNES, "", fixed = TRUE)[[1]]

  categorias <- c(
    minusculas = sum(chars %in% letters),
    mayusculas = sum(chars %in% LETTERS),
    numeros    = sum(chars %in% as.character(0:9)),
    simbolos   = sum(chars %in% simb),
    unicode    = sum(!(chars %in% c(letters, LETTERS, as.character(0:9), simb)))
  )

  charset_size <- 0L
  if (categorias[["minusculas"]] > 0L) charset_size <- charset_size + .TAM_MINUSCULAS
  if (categorias[["mayusculas"]] > 0L) charset_size <- charset_size + .TAM_MAYUSCULAS
  if (categorias[["numeros"]]    > 0L) charset_size <- charset_size + .TAM_NUMEROS
  if (categorias[["simbolos"]]   > 0L) charset_size <- charset_size + .TAM_SIMBOLOS

  list(
    longitud       = length(chars),
    charset_size   = charset_size,
    categorias     = categorias,
    unicode_present = categorias[["unicode"]] > 0L,
    unicode_count  = categorias[["unicode"]]
  )
}

# --- Entropía ----------------------------------------------------------------

#' Entropía teórica y ajustada por patrones.
#' `entropia_ajustada_bits = entropia_teorica_bits - penalizacion_bits`.
#' Para contraseñas de solo Unicode (charset 0) devuelve NA en la ajustada:
#' no se puede estimar sin asumir un espacio de caracteres (honestidad > número).
calcular_entropia <- function(password) {
  cs <- calcular_charset(password)
  if (cs$longitud == 0L) {
    return(list(
      longitud = 0L, charset_size = 0L,
      entropia_teorica_bits = 0,
      entropia_ajustada_bits = 0,
      bits_penalizados = 0,
      patrones = list(patrones_encontrados = FALSE),
      nota = "contraseña vacía"
    ))
  }

  # Con solo Unicode, la matemática del charset no aplica (no asumimos tamaño).
  if (cs$charset_size == 0L) {
    return(list(
      longitud = cs$longitud, charset_size = 0L,
      entropia_teorica_bits = NA_real_,
      entropia_ajustada_bits = NA_real_,
      bits_penalizados = NA_real_,
      patrones = list(patrones_encontrados = FALSE),
      nota = "solo caracteres Unicode: no se estima sin asumir un espacio de caracteres"
    ))
  }

  bits_teoricos <- cs$longitud * log2(cs$charset_size)
  patrones <- detectar_patrones(password, charset_size = cs$charset_size)

  bits_efectivos <- max(bits_teoricos - patrones$penalizacion_bits, 0)

  # Cobertura del diccionario: si la palabra cubre >= 50% de la contraseña,
  # es "básicamente una palabra del diccionario" → tope honesto (log2(200)~8 bits).
  if (patrones$cobertura_diccionario >= 0.5) {
    bits_efectivos <- min(bits_efectivos, .LIMITE_BITS_DICCIONARIO)
  }

  # Si hay Unicode mezclado, el resultado es una cota inferior conservadora.
  nota <- if (cs$unicode_present) {
    "cálculo conservador: los caracteres Unicode suman longitud pero no charset asumido"
  } else {
    NULL
  }

  list(
    longitud = cs$longitud,
    charset_size = cs$charset_size,
    entropia_teorica_bits = bits_teoricos,
    entropia_ajustada_bits = bits_efectivos,
    bits_penalizados = patrones$penalizacion_bits,
    patrones = patrones,
    nota = nota
  )
}

# --- Tiempo estimado ----------------------------------------------------------

#' Convierte entropía (bits) a tiempo de crackeo en segundos.
#' Acepta un número (bits) o el resultado de `calcular_entropia()` (usa la
#' entropía ajustada). Devuelve segundos (Inf si no entra en un double) más el
#' valor en log10 para que el formateo siga siendo preciso.
tiempo_estimado <- function(entropia, velocidad = VELOCIDAD_DEFAULT) {
  bits <- if (is.list(entropia)) entropia$entropia_ajustada_bits else entropia
  if (is.na(bits)) {
    return(list(segundos = NA_real_, log10_segundos = NA_real_,
                bits = NA_real_, velocidad = velocidad, calculable = FALSE))
  }
  bits <- max(bits, 0)
  log10_seg <- bits * log10(2) - log10(velocidad)
  seg <- if (log10_seg > 308) Inf else 10^log10_seg
  list(segundos = seg, log10_segundos = log10_seg,
       bits = bits, velocidad = velocidad, calculable = TRUE)
}

# --- Formateo de tiempo a lenguaje humano --------------------------------------

#' Formatea segundos (o log10 de segundos) a una unidad legible en español.
#' Unidades: instantáneo, segundos, minutos, horas, días, años, mil años,
#' millones de años, mil millones de años y "más que la edad del universo".
#' Edad del universo ≈ 13.800 millones de años = 4.354e17 s.
formatear_tiempo <- function(segundos, log10_segundos = NULL) {
  if (!is.null(log10_segundos) && !is.na(log10_segundos)) {
    log10_t <- log10_segundos
  } else if (!is.na(segundos) && is.finite(segundos) && segundos >= 0) {
    log10_t <- log10(segundos)
  } else if (is.na(segundos)) {
    return("no calculable")
  } else {
    return("más que la edad del universo")
  }

  # Umbrales en log10(segundos)
  .SEC <- 0
  .MIN <- log10(60)
  .HOR <- log10(3600)
  .DIA <- log10(86400)
  .ANY <- log10(31557600)          # año juliano
  .MIL <- log10(3.15576e10)        # 1000 años
  .MILL <- log10(3.15576e13)       # 1 millón de años
  .MMIL <- log10(3.15576e16)       # 1000 millones de años
  .UNIV <- log10(4.354e17)         # edad del universo

  unidad <- "instantáneo"
  valor <- NULL
  if (log10_t < .SEC) {
    unidad <- "instantáneo"
  } else if (log10_t < .MIN) {
    unidad <- "segundos";  valor <- 10^log10_t
  } else if (log10_t < .HOR) {
    unidad <- "minutos";   valor <- 10^log10_t / 60
  } else if (log10_t < .DIA) {
    unidad <- "horas";     valor <- 10^log10_t / 3600
  } else if (log10_t < .ANY) {
    unidad <- "días";      valor <- 10^log10_t / 86400
  } else if (log10_t < .MIL) {
    unidad <- "años";      valor <- 10^log10_t / 31557600
  } else if (log10_t < .MILL) {
    unidad <- "mil años";  valor <- 10^log10_t / 3.15576e10
  } else if (log10_t < .MMIL) {
    unidad <- "millones de años"; valor <- 10^log10_t / 3.15576e13
  } else if (log10_t < .UNIV) {
    unidad <- "mil millones de años"; valor <- 10^log10_t / 3.15576e16
  } else {
    unidad <- "más que la edad del universo"
  }

  if (unidad == "instantáneo") return("instantáneo")
  if (unidad == "más que la edad del universo") return("más que la edad del universo")

  # Redondeo para absorber el ruido de punto flotante (10^log10 puede dar
  # 0.9999999 en vez de 1).
  valor <- round(valor, 6)

  n <- .numero_es(if (unidad %in% c("mil años")) round(valor) else valor)
  singulares <- c(segundos = "segundo", minutos = "minuto", horas = "hora",
                  días = "día", años = "año", `mil años` = "mil años",
                  `millones de años` = "millón de años",
                  `mil millones de años` = "mil millones de años")
  nombre <- singulares[[unidad]]
  plural <- isTRUE(valor > 1 || valor != round(valor))
  if (plural) {
    if (unidad == "segundos")  nombre <- "segundos"
    if (unidad == "minutos")   nombre <- "minutos"
    if (unidad == "horas")     nombre <- "horas"
    if (unidad == "días")      nombre <- "días"
    if (unidad == "años")      nombre <- "años"
    if (unidad == "mil años")  nombre <- "mil años"
    if (unidad == "millones de años")      nombre <- "millones de años"
    if (unidad == "mil millones de años")  nombre <- "mil millones de años"
  }
  paste(n, nombre)
}

# Redondeo bonito: 2 cifras significativas, coma decimal, punto de miles.
.numero_es <- function(x) {
  r <- signif(x, 2)
  if (r >= 100) return(formatC(round(r), format = "d", big.mark = ".", decimal.mark = ","))
  if (r == round(r)) return(formatC(r, format = "d", big.mark = ".", decimal.mark = ","))
  dec <- if (r >= 10) 1 else 1
  sub("\\.", ",", formatC(r, format = "f", digits = dec, decimal.mark = ","))
}

# Operador %||% (evita depender de rlang). Tolera closure/NA sin warnings.
`%||%` <- function(a, b) {
  if (is.null(a)) return(b)
  if (!is.atomic(a)) return(a)
  if (length(a) == 0L) return(b)
  if (is.na(a)) return(b)
  a
}

